-- name: AdminActivityCount :one
WITH display_activity AS (SELECT a.*, CAST(coalesce((SELECT i.ticker FROM instruments i WHERE i.id=json_extract(a.snapshot,'$.activity.instrument_id')),'') AS TEXT) AS instrument_ticker, e.account_id, accounts.name AS account_name FROM admin_activity a JOIN executions e ON e.id=a.id JOIN accounts ON accounts.id=e.account_id)
SELECT (SELECT count(*) FROM admin_activity) AS total,count(*) AS matched FROM display_activity WHERE (CAST(sqlc.arg(account_filter) AS TEXT)='' OR account_id=sqlc.arg(account_filter)) AND (sqlc.arg(kind_filter)='' OR kind=sqlc.arg(kind_filter))
 AND (sqlc.arg(state_filter)='' OR sqlc.arg(state_filter)='review' AND review_reasons<>0 OR status=sqlc.arg(state_filter))
 AND (sqlc.arg(search)='' OR wake_contains(search_text,sqlc.arg(search))=1 OR wake_contains(label_sort,sqlc.arg(search))=1 OR wake_contains(coalesce(json_extract(snapshot,'$.activity.transfer.direction'),'') || ' ' || coalesce(json_extract(snapshot,'$.activity.transfer.method'),'') || ' ' || coalesce(json_extract(snapshot,'$.activity.transfer.price.amount'),'') || ' ' || coalesce(json_extract(snapshot,'$.activity.transfer.price.currency'),'') || ' ' || coalesce(json_extract(snapshot,'$.activity.cash.category'),'') || ' ' || coalesce(json_extract(snapshot,'$.activity.cash.description'),'') || ' ' || coalesce(json_extract(snapshot,'$.activity.cash.amount.amount'),'') || ' ' || coalesce(json_extract(snapshot,'$.activity.cash.amount.currency'),''),sqlc.arg(search))=1
 OR kind='security-transfer' AND json_extract(sqlc.arg(activity_text),'$.transfer_prefix')<>'' AND wake_contains(json_extract(sqlc.arg(activity_text),'$.transfer_prefix') || coalesce(json_extract(snapshot,'$.activity.transfer.direction'),'') || json_extract(sqlc.arg(activity_text),'$.movement_separator') || coalesce(nullif(instrument_ticker,''),nullif(instrument_name,''),json_extract(sqlc.arg(activity_text),'$.unknown')),sqlc.arg(search))=1
 OR kind='cash' AND json_extract(sqlc.arg(activity_text),'$.movement_separator')<>'' AND wake_contains(replace(json_extract(snapshot,'$.activity.cash.category'),'-',' ') || json_extract(sqlc.arg(activity_text),'$.movement_separator') || coalesce(nullif(json_extract(snapshot,'$.activity.cash.description'),''),json_extract(sqlc.arg(activity_text),'$.unknown')),sqlc.arg(search))=1
 OR sqlc.arg(missing_values)=1 AND (kind<>'cash' AND realized IS NULL OR kind='cash' AND coalesce(json_extract(snapshot,'$.activity.cash.description'),'')='' OR (kind NOT IN ('conversion','cash') AND instrument_name='') OR kind='trade' AND (quantity IS NULL OR price IS NULL) OR kind='conversion' AND (price IS NULL OR json_extract(snapshot,'$.activity.sent.amount') IS NULL OR json_extract(snapshot,'$.activity.received.amount') IS NULL OR coalesce(json_extract(snapshot,'$.activity.sent.currency'),'')='' OR coalesce(json_extract(snapshot,'$.activity.received.currency'),'')='' OR json_extract(snapshot,'$.activity.rate_base') IS NULL))
 OR sqlc.arg(inapplicable_values)=1
 OR kind IN ('trade','lifecycle') AND json_extract(sqlc.arg(activity_text),'$.unknown')<>'' AND wake_contains(coalesce(json_extract(json_extract(snapshot,'$.activity'),'$.side'),json_extract(json_extract(snapshot,'$.activity'),'$.lifecycle_kind')) || CASE WHEN kind='lifecycle' THEN json_extract(sqlc.arg(activity_text),'$.lifecycle_separator') ELSE ' ' END || coalesce(nullif(instrument_ticker,''),nullif(instrument_name,''),json_extract(sqlc.arg(activity_text),'$.unknown')),sqlc.arg(search))=1
 OR kind='conversion' AND json_extract(sqlc.arg(activity_text),'$.pair_separator')<>'' AND (wake_contains(json_extract(sqlc.arg(activity_text),'$.conversion_prefix') || coalesce(nullif(json_extract(json_extract(snapshot,'$.activity'),'$.sent.currency'),''),json_extract(sqlc.arg(activity_text),'$.unknown')) || json_extract(sqlc.arg(activity_text),'$.pair_separator') || coalesce(nullif(json_extract(json_extract(snapshot,'$.activity'),'$.received.currency'),''),json_extract(sqlc.arg(activity_text),'$.unknown')),sqlc.arg(search))=1 OR wake_contains(coalesce(json_extract(json_extract(snapshot,'$.activity'),'$.sent.amount'),json_extract(sqlc.arg(activity_text),'$.unknown')) || ' ' || coalesce(nullif(json_extract(json_extract(snapshot,'$.activity'),'$.sent.currency'),''),json_extract(sqlc.arg(activity_text),'$.unknown')) || ' ' || json_extract(sqlc.arg(activity_text),'$.sent') || json_extract(sqlc.arg(activity_text),'$.amount_separator') || coalesce(json_extract(json_extract(snapshot,'$.activity'),'$.received.amount'),json_extract(sqlc.arg(activity_text),'$.unknown')) || ' ' || coalesce(nullif(json_extract(json_extract(snapshot,'$.activity'),'$.received.currency'),''),json_extract(sqlc.arg(activity_text),'$.unknown')) || ' ' || json_extract(sqlc.arg(activity_text),'$.received'),sqlc.arg(search))=1)
 OR EXISTS(SELECT 1 FROM json_each(sqlc.arg(kind_matches)) match WHERE match.value=display_activity.kind)
 OR EXISTS(SELECT 1 FROM json_each(sqlc.arg(state_matches)) match WHERE json_extract(match.value,'$.lifecycle')=status AND json_extract(match.value,'$.review')=review_reasons AND json_extract(match.value,'$.authority')=selection_authority)
 OR EXISTS(SELECT 1 FROM json_each(sqlc.arg(reference_matches)) match WHERE json_extract(match.value,'$.status')=reference_status AND json_extract(match.value,'$.authority')=reference_authority));
-- name: AdminActivityRows :many
WITH display_activity AS (SELECT a.*, CAST(coalesce((SELECT i.ticker FROM instruments i WHERE i.id=json_extract(a.snapshot,'$.activity.instrument_id')),'') AS TEXT) AS instrument_ticker, e.account_id, accounts.name AS account_name FROM admin_activity a JOIN executions e ON e.id=a.id JOIN accounts ON accounts.id=e.account_id), ordering AS (SELECT CAST(sqlc.arg(sort_field) AS TEXT) AS sort_field,CAST(sqlc.arg(direction) AS TEXT) AS direction,CAST(sqlc.arg(activity_text) AS TEXT) AS activity_text)
SELECT snapshot,status,review_reasons,selection_authority,instrument_name,instrument_ticker,reference_status,reference_authority,account_name FROM display_activity CROSS JOIN ordering WHERE (CAST(sqlc.arg(account_filter) AS TEXT)='' OR account_id=sqlc.arg(account_filter)) AND (sqlc.arg(kind_filter)='' OR kind=sqlc.arg(kind_filter))
 AND (sqlc.arg(state_filter)='' OR sqlc.arg(state_filter)='review' AND review_reasons<>0 OR status=sqlc.arg(state_filter))
 AND (sqlc.arg(search)='' OR wake_contains(search_text,sqlc.arg(search))=1 OR wake_contains(label_sort,sqlc.arg(search))=1 OR wake_contains(coalesce(json_extract(snapshot,'$.activity.transfer.direction'),'') || ' ' || coalesce(json_extract(snapshot,'$.activity.transfer.method'),'') || ' ' || coalesce(json_extract(snapshot,'$.activity.transfer.price.amount'),'') || ' ' || coalesce(json_extract(snapshot,'$.activity.transfer.price.currency'),'') || ' ' || coalesce(json_extract(snapshot,'$.activity.cash.category'),'') || ' ' || coalesce(json_extract(snapshot,'$.activity.cash.description'),'') || ' ' || coalesce(json_extract(snapshot,'$.activity.cash.amount.amount'),'') || ' ' || coalesce(json_extract(snapshot,'$.activity.cash.amount.currency'),''),sqlc.arg(search))=1
 OR kind='security-transfer' AND json_extract(sqlc.arg(activity_text),'$.transfer_prefix')<>'' AND wake_contains(json_extract(sqlc.arg(activity_text),'$.transfer_prefix') || coalesce(json_extract(snapshot,'$.activity.transfer.direction'),'') || json_extract(sqlc.arg(activity_text),'$.movement_separator') || coalesce(nullif(instrument_ticker,''),nullif(instrument_name,''),json_extract(sqlc.arg(activity_text),'$.unknown')),sqlc.arg(search))=1
 OR kind='cash' AND json_extract(sqlc.arg(activity_text),'$.movement_separator')<>'' AND wake_contains(replace(json_extract(snapshot,'$.activity.cash.category'),'-',' ') || json_extract(sqlc.arg(activity_text),'$.movement_separator') || coalesce(nullif(json_extract(snapshot,'$.activity.cash.description'),''),json_extract(sqlc.arg(activity_text),'$.unknown')),sqlc.arg(search))=1
 OR sqlc.arg(missing_values)=1 AND (kind<>'cash' AND realized IS NULL OR kind='cash' AND coalesce(json_extract(snapshot,'$.activity.cash.description'),'')='' OR (kind NOT IN ('conversion','cash') AND instrument_name='') OR kind='trade' AND (quantity IS NULL OR price IS NULL) OR kind='conversion' AND (price IS NULL OR json_extract(snapshot,'$.activity.sent.amount') IS NULL OR json_extract(snapshot,'$.activity.received.amount') IS NULL OR coalesce(json_extract(snapshot,'$.activity.sent.currency'),'')='' OR coalesce(json_extract(snapshot,'$.activity.received.currency'),'')='' OR json_extract(snapshot,'$.activity.rate_base') IS NULL))
 OR sqlc.arg(inapplicable_values)=1
 OR kind IN ('trade','lifecycle') AND json_extract(sqlc.arg(activity_text),'$.unknown')<>'' AND wake_contains(coalesce(json_extract(json_extract(snapshot,'$.activity'),'$.side'),json_extract(json_extract(snapshot,'$.activity'),'$.lifecycle_kind')) || CASE WHEN kind='lifecycle' THEN json_extract(sqlc.arg(activity_text),'$.lifecycle_separator') ELSE ' ' END || coalesce(nullif(instrument_ticker,''),nullif(instrument_name,''),json_extract(sqlc.arg(activity_text),'$.unknown')),sqlc.arg(search))=1
 OR kind='conversion' AND json_extract(sqlc.arg(activity_text),'$.pair_separator')<>'' AND (wake_contains(json_extract(sqlc.arg(activity_text),'$.conversion_prefix') || coalesce(nullif(json_extract(json_extract(snapshot,'$.activity'),'$.sent.currency'),''),json_extract(sqlc.arg(activity_text),'$.unknown')) || json_extract(sqlc.arg(activity_text),'$.pair_separator') || coalesce(nullif(json_extract(json_extract(snapshot,'$.activity'),'$.received.currency'),''),json_extract(sqlc.arg(activity_text),'$.unknown')),sqlc.arg(search))=1 OR wake_contains(coalesce(json_extract(json_extract(snapshot,'$.activity'),'$.sent.amount'),json_extract(sqlc.arg(activity_text),'$.unknown')) || ' ' || coalesce(nullif(json_extract(json_extract(snapshot,'$.activity'),'$.sent.currency'),''),json_extract(sqlc.arg(activity_text),'$.unknown')) || ' ' || json_extract(sqlc.arg(activity_text),'$.sent') || json_extract(sqlc.arg(activity_text),'$.amount_separator') || coalesce(json_extract(json_extract(snapshot,'$.activity'),'$.received.amount'),json_extract(sqlc.arg(activity_text),'$.unknown')) || ' ' || coalesce(nullif(json_extract(json_extract(snapshot,'$.activity'),'$.received.currency'),''),json_extract(sqlc.arg(activity_text),'$.unknown')) || ' ' || json_extract(sqlc.arg(activity_text),'$.received'),sqlc.arg(search))=1)
 OR EXISTS(SELECT 1 FROM json_each(sqlc.arg(kind_matches)) match WHERE match.value=display_activity.kind)
 OR EXISTS(SELECT 1 FROM json_each(sqlc.arg(state_matches)) match WHERE json_extract(match.value,'$.lifecycle')=status AND json_extract(match.value,'$.review')=review_reasons AND json_extract(match.value,'$.authority')=selection_authority)
 OR EXISTS(SELECT 1 FROM json_each(sqlc.arg(reference_matches)) match WHERE json_extract(match.value,'$.status')=reference_status AND json_extract(match.value,'$.authority')=reference_authority))
 ORDER BY
 CASE ordering.sort_field WHEN 'quantity' THEN quantity IS NULL WHEN 'price' THEN coalesce(price,json_extract(snapshot,'$.activity.transfer.price.amount')) IS NULL WHEN 'amount' THEN json_extract(snapshot,'$.activity.cash.amount.amount') IS NULL WHEN 'realized' THEN realized IS NULL ELSE 0 END ASC,
 CASE ordering.sort_field WHEN 'quantity' THEN quantity_unit WHEN 'price' THEN coalesce(nullif(price_unit,''),json_extract(snapshot,'$.activity.transfer.price.currency'),'') WHEN 'amount' THEN json_extract(snapshot,'$.activity.cash.amount.currency') WHEN 'realized' THEN realized_currency ELSE '' END ASC,
 CASE WHEN ordering.sort_field='quantity' AND ordering.direction='asc' THEN quantity END COLLATE wake_decimal ASC,
 CASE WHEN ordering.sort_field='quantity' AND ordering.direction='desc' THEN quantity END COLLATE wake_decimal DESC,
 CASE WHEN ordering.sort_field='price' AND ordering.direction='asc' THEN coalesce(price,json_extract(snapshot,'$.activity.transfer.price.amount')) END COLLATE wake_decimal ASC,
 CASE WHEN ordering.sort_field='price' AND ordering.direction='desc' THEN coalesce(price,json_extract(snapshot,'$.activity.transfer.price.amount')) END COLLATE wake_decimal DESC,
 CASE WHEN ordering.sort_field='amount' AND ordering.direction='asc' THEN json_extract(snapshot,'$.activity.cash.amount.amount') END COLLATE wake_decimal ASC,
 CASE WHEN ordering.sort_field='amount' AND ordering.direction='desc' THEN json_extract(snapshot,'$.activity.cash.amount.amount') END COLLATE wake_decimal DESC,
 CASE WHEN ordering.sort_field='realized' AND ordering.direction='asc' THEN realized END COLLATE wake_decimal ASC,
 CASE WHEN ordering.sort_field='realized' AND ordering.direction='desc' THEN realized END COLLATE wake_decimal DESC,
 CASE WHEN ordering.direction='asc' THEN CASE ordering.sort_field WHEN 'date' THEN event_date WHEN 'label' THEN lower(CASE WHEN kind='cash' THEN replace(json_extract(snapshot,'$.activity.cash.category'),'-',' ') || coalesce(nullif(json_extract(ordering.activity_text,'$.movement_separator'),''),char(32,183,32)) || coalesce(nullif(json_extract(snapshot,'$.activity.cash.description'),''),nullif(json_extract(ordering.activity_text,'$.unknown'),''),'Unknown') WHEN kind='security-transfer' THEN coalesce(nullif(json_extract(ordering.activity_text,'$.transfer_prefix'),''),'Transfer ') || json_extract(snapshot,'$.activity.transfer.direction') || coalesce(nullif(json_extract(ordering.activity_text,'$.movement_separator'),''),char(32,183,32)) || coalesce(nullif(instrument_ticker,''),nullif(instrument_name,''),nullif(json_extract(ordering.activity_text,'$.unknown'),''),'Unknown') WHEN kind IN ('trade','lifecycle') THEN coalesce(json_extract(snapshot,'$.activity.side'),json_extract(snapshot,'$.activity.lifecycle_kind')) || CASE WHEN kind='lifecycle' THEN coalesce(nullif(json_extract(ordering.activity_text,'$.lifecycle_separator'),''),char(32,183,32)) ELSE ' ' END || coalesce(nullif(instrument_ticker,''),nullif(instrument_name,''),nullif(json_extract(ordering.activity_text,'$.unknown'),''),'Unknown') ELSE label_sort END) WHEN 'state' THEN status WHEN 'reference' THEN reference_status END END ASC,
 CASE WHEN ordering.direction='desc' THEN CASE ordering.sort_field WHEN 'date' THEN event_date WHEN 'label' THEN lower(CASE WHEN kind='cash' THEN replace(json_extract(snapshot,'$.activity.cash.category'),'-',' ') || coalesce(nullif(json_extract(ordering.activity_text,'$.movement_separator'),''),char(32,183,32)) || coalesce(nullif(json_extract(snapshot,'$.activity.cash.description'),''),nullif(json_extract(ordering.activity_text,'$.unknown'),''),'Unknown') WHEN kind='security-transfer' THEN coalesce(nullif(json_extract(ordering.activity_text,'$.transfer_prefix'),''),'Transfer ') || json_extract(snapshot,'$.activity.transfer.direction') || coalesce(nullif(json_extract(ordering.activity_text,'$.movement_separator'),''),char(32,183,32)) || coalesce(nullif(instrument_ticker,''),nullif(instrument_name,''),nullif(json_extract(ordering.activity_text,'$.unknown'),''),'Unknown') WHEN kind IN ('trade','lifecycle') THEN coalesce(json_extract(snapshot,'$.activity.side'),json_extract(snapshot,'$.activity.lifecycle_kind')) || CASE WHEN kind='lifecycle' THEN coalesce(nullif(json_extract(ordering.activity_text,'$.lifecycle_separator'),''),char(32,183,32)) ELSE ' ' END || coalesce(nullif(instrument_ticker,''),nullif(instrument_name,''),nullif(json_extract(ordering.activity_text,'$.unknown'),''),'Unknown') ELSE label_sort END) WHEN 'state' THEN status WHEN 'reference' THEN reference_status END END DESC,
 CASE WHEN ordering.sort_field='reference' AND ordering.direction='asc' THEN reference_authority END ASC,
 CASE WHEN ordering.sort_field='reference' AND ordering.direction='desc' THEN reference_authority END DESC,
 id ASC LIMIT sqlc.arg(page_size) OFFSET sqlc.arg(page_offset);
-- name: AdminInstrumentCount :one
SELECT (SELECT count(*) FROM admin_instruments) AS total,count(*) AS matched FROM admin_instruments WHERE (sqlc.arg(kind_filter)='' OR kind=sqlc.arg(kind_filter))
 AND (sqlc.arg(state_filter)='' OR sqlc.arg(state_filter)='review' AND reference_status IN ('ambiguous','conflict') OR sqlc.arg(state_filter)='gaps' AND reference_status NOT IN ('resolved','ambiguous','conflict') OR reference_status=sqlc.arg(state_filter))
 AND (sqlc.arg(search)='' OR wake_contains(search_text,sqlc.arg(search))=1 OR sqlc.arg(missing_values)=1 AND (name='' OR ticker='')
 OR EXISTS(SELECT 1 FROM json_each(sqlc.arg(reference_matches)) match WHERE json_extract(match.value,'$.status')=reference_status AND json_extract(match.value,'$.authority')=selection_authority));
-- name: AdminInstrumentRows :many
WITH ordering AS (SELECT CAST(sqlc.arg(sort_field) AS TEXT) AS sort_field,CAST(sqlc.arg(direction) AS TEXT) AS direction)
SELECT snapshot,selection_authority FROM admin_instruments CROSS JOIN ordering WHERE (sqlc.arg(kind_filter)='' OR kind=sqlc.arg(kind_filter))
 AND (sqlc.arg(state_filter)='' OR sqlc.arg(state_filter)='review' AND reference_status IN ('ambiguous','conflict') OR sqlc.arg(state_filter)='gaps' AND reference_status NOT IN ('resolved','ambiguous','conflict') OR reference_status=sqlc.arg(state_filter))
 AND (sqlc.arg(search)='' OR wake_contains(search_text,sqlc.arg(search))=1 OR sqlc.arg(missing_values)=1 AND (name='' OR ticker='')
 OR EXISTS(SELECT 1 FROM json_each(sqlc.arg(reference_matches)) match WHERE json_extract(match.value,'$.status')=reference_status AND json_extract(match.value,'$.authority')=selection_authority))
 ORDER BY
 CASE ordering.sort_field WHEN 'name' THEN name='' ELSE 0 END ASC,
 CASE WHEN ordering.direction='asc' THEN CASE ordering.sort_field WHEN 'name' THEN name WHEN 'ticker' THEN coalesce(nullif(ticker,''),nullif(name,''),'Unknown') WHEN 'kind' THEN kind WHEN 'state' THEN reference_status END END COLLATE NOCASE ASC,
 CASE WHEN ordering.direction='desc' THEN CASE ordering.sort_field WHEN 'name' THEN name WHEN 'ticker' THEN coalesce(nullif(ticker,''),nullif(name,''),'Unknown') WHEN 'kind' THEN kind WHEN 'state' THEN reference_status END END COLLATE NOCASE DESC,
 CASE WHEN ordering.sort_field='state' AND ordering.direction='asc' THEN selection_authority END ASC,
 CASE WHEN ordering.sort_field='state' AND ordering.direction='desc' THEN selection_authority END DESC,
 id ASC LIMIT sqlc.arg(page_size) OFFSET sqlc.arg(page_offset);
-- name: AdminCounts :one
SELECT (SELECT count(*) FROM published_resources WHERE kind='activity') AS activity_count,(SELECT count(*) FROM published_resources WHERE kind='instruments') AS instrument_count,(SELECT count(*) FROM connections) AS connection_count;
-- name: AdminReferenceStatus :one
SELECT length(encrypted)>0 AS has_key,failure FROM access.reference_settings WHERE singleton=1;
-- name: AdminSourceCount :one
SELECT count(*) FROM connections WHERE sqlc.arg(search)='' OR wake_contains(name || ' ' || provider,sqlc.arg(search))=1;
-- name: AdminSourceRows :many
SELECT * FROM connections WHERE sqlc.arg(search)='' OR wake_contains(name || ' ' || provider,sqlc.arg(search))=1 ORDER BY name COLLATE NOCASE,id LIMIT sqlc.arg(page_size) OFFSET sqlc.arg(page_offset);

-- name: AdminCandidateCount :one
SELECT count(*) FROM (SELECT authority,kind,scope,value FROM eligible_candidates WHERE connection_id=? GROUP BY authority,kind,scope,value);
-- name: AdminCandidates :many
SELECT artifact_id,authority,kind,scope,value,name,currency FROM (
 SELECT c.*,c.sequence AS appearance,row_number() OVER(PARTITION BY c.authority,c.kind,c.scope,c.value ORDER BY c.sequence DESC) AS ranking
 FROM eligible_candidates c WHERE c.connection_id=sqlc.arg(connection_id)
) WHERE ranking=1 ORDER BY appearance DESC,authority,kind,scope,value LIMIT sqlc.arg(page_size) OFFSET sqlc.arg(page_offset);

-- name: AdminReviewCount :one
WITH display_review AS (SELECT r.*, CAST(coalesce((SELECT i.ticker FROM instruments i WHERE i.id=CASE WHEN r.kind='instrument' THEN r.id ELSE json_extract(nullif(r.activity,''),'$.instrument_id') END),'') AS TEXT) AS ticker FROM admin_review r)
SELECT (SELECT count(*) FROM admin_review) AS total,count(*) AS matched FROM display_review WHERE sqlc.arg(search)='' OR wake_contains(search_text || ' ' || kind || ' ' || id,sqlc.arg(search))=1 OR label_key<>'' AND wake_contains(label_key,sqlc.arg(search))=1 OR kind='activity' AND json_extract(activity,'$.family')='cash' AND wake_contains(coalesce(json_extract(activity,'$.cash.description'),''),sqlc.arg(search))=1 OR kind='activity' AND json_extract(activity,'$.family')='security-transfer' AND json_extract(sqlc.arg(activity_text),'$.transfer_prefix')<>'' AND wake_contains(json_extract(sqlc.arg(activity_text),'$.transfer_prefix') || coalesce(json_extract(activity,'$.transfer.direction'),'') || json_extract(sqlc.arg(activity_text),'$.movement_separator') || coalesce(nullif(ticker,''),nullif(name,''),json_extract(sqlc.arg(activity_text),'$.unknown')),sqlc.arg(search))=1 OR kind='activity' AND json_extract(activity,'$.family')='cash' AND json_extract(sqlc.arg(activity_text),'$.movement_separator')<>'' AND wake_contains(replace(json_extract(activity,'$.cash.category'),'-',' ') || json_extract(sqlc.arg(activity_text),'$.movement_separator') || coalesce(nullif(json_extract(activity,'$.cash.description'),''),json_extract(sqlc.arg(activity_text),'$.unknown')),sqlc.arg(search))=1 OR kind='activity' AND json_extract(activity,'$.family') IN ('trade','lifecycle') AND json_extract(sqlc.arg(activity_text),'$.unknown')<>'' AND wake_contains(coalesce(json_extract(activity,'$.side'),json_extract(activity,'$.lifecycle_kind')) || CASE WHEN json_extract(activity,'$.family')='lifecycle' THEN json_extract(sqlc.arg(activity_text),'$.lifecycle_separator') ELSE ' ' END || coalesce(nullif(ticker,''),nullif(name,''),json_extract(sqlc.arg(activity_text),'$.unknown')),sqlc.arg(search))=1 OR kind='activity' AND json_extract(activity,'$.family')='conversion' AND json_extract(sqlc.arg(activity_text),'$.pair_separator')<>'' AND wake_contains(json_extract(sqlc.arg(activity_text),'$.conversion_prefix') || coalesce(nullif(json_extract(activity,'$.sent.currency'),''),json_extract(sqlc.arg(activity_text),'$.unknown')) || json_extract(sqlc.arg(activity_text),'$.pair_separator') || coalesce(nullif(json_extract(activity,'$.received.currency'),''),json_extract(sqlc.arg(activity_text),'$.unknown')),sqlc.arg(search))=1 OR sqlc.arg(missing_values)=1 AND (kind='instrument' AND name='' OR kind='activity' AND (json_extract(activity,'$.family')='cash' AND coalesce(json_extract(activity,'$.cash.description'),'')='' OR json_extract(activity,'$.family') NOT IN ('conversion','cash') AND name='')) OR EXISTS(SELECT 1 FROM json_each(sqlc.arg(kind_matches)) match WHERE kind='activity' AND json_extract(activity,'$.family')=match.value) OR EXISTS(SELECT 1 FROM json_each(sqlc.arg(review_matches)) match WHERE json_extract(match.value,'$.kind')=display_review.kind AND (json_extract(match.value,'$.status')='' OR json_extract(match.value,'$.status')=display_review.status) AND (json_extract(match.value,'$.count_known')<>1 OR json_extract(match.value,'$.count')=claim_count));
-- name: AdminReviewRows :many
WITH display_review AS (SELECT r.*, CAST(coalesce((SELECT i.ticker FROM instruments i WHERE i.id=CASE WHEN r.kind='instrument' THEN r.id ELSE json_extract(nullif(r.activity,''),'$.instrument_id') END),'') AS TEXT) AS ticker FROM admin_review r)
SELECT CAST(kind AS TEXT) AS kind,CAST(id AS TEXT) AS id,CAST(name AS TEXT) AS name,ticker,CAST(artifact AS TEXT) AS artifact,CAST(location AS TEXT) AS location,CAST(status AS TEXT) AS status,CAST(claim_count AS INTEGER) AS claim_count,CAST(activity AS TEXT) AS activity FROM display_review WHERE sqlc.arg(search)='' OR wake_contains(search_text || ' ' || kind || ' ' || id,sqlc.arg(search))=1 OR label_key<>'' AND wake_contains(label_key,sqlc.arg(search))=1 OR kind='activity' AND json_extract(activity,'$.family')='cash' AND wake_contains(coalesce(json_extract(activity,'$.cash.description'),''),sqlc.arg(search))=1 OR kind='activity' AND json_extract(activity,'$.family')='security-transfer' AND json_extract(sqlc.arg(activity_text),'$.transfer_prefix')<>'' AND wake_contains(json_extract(sqlc.arg(activity_text),'$.transfer_prefix') || coalesce(json_extract(activity,'$.transfer.direction'),'') || json_extract(sqlc.arg(activity_text),'$.movement_separator') || coalesce(nullif(ticker,''),nullif(name,''),json_extract(sqlc.arg(activity_text),'$.unknown')),sqlc.arg(search))=1 OR kind='activity' AND json_extract(activity,'$.family')='cash' AND json_extract(sqlc.arg(activity_text),'$.movement_separator')<>'' AND wake_contains(replace(json_extract(activity,'$.cash.category'),'-',' ') || json_extract(sqlc.arg(activity_text),'$.movement_separator') || coalesce(nullif(json_extract(activity,'$.cash.description'),''),json_extract(sqlc.arg(activity_text),'$.unknown')),sqlc.arg(search))=1 OR kind='activity' AND json_extract(activity,'$.family') IN ('trade','lifecycle') AND json_extract(sqlc.arg(activity_text),'$.unknown')<>'' AND wake_contains(coalesce(json_extract(activity,'$.side'),json_extract(activity,'$.lifecycle_kind')) || CASE WHEN json_extract(activity,'$.family')='lifecycle' THEN json_extract(sqlc.arg(activity_text),'$.lifecycle_separator') ELSE ' ' END || coalesce(nullif(ticker,''),nullif(name,''),json_extract(sqlc.arg(activity_text),'$.unknown')),sqlc.arg(search))=1 OR kind='activity' AND json_extract(activity,'$.family')='conversion' AND json_extract(sqlc.arg(activity_text),'$.pair_separator')<>'' AND wake_contains(json_extract(sqlc.arg(activity_text),'$.conversion_prefix') || coalesce(nullif(json_extract(activity,'$.sent.currency'),''),json_extract(sqlc.arg(activity_text),'$.unknown')) || json_extract(sqlc.arg(activity_text),'$.pair_separator') || coalesce(nullif(json_extract(activity,'$.received.currency'),''),json_extract(sqlc.arg(activity_text),'$.unknown')),sqlc.arg(search))=1 OR sqlc.arg(missing_values)=1 AND (kind='instrument' AND name='' OR kind='activity' AND (json_extract(activity,'$.family')='cash' AND coalesce(json_extract(activity,'$.cash.description'),'')='' OR json_extract(activity,'$.family') NOT IN ('conversion','cash') AND name='')) OR EXISTS(SELECT 1 FROM json_each(sqlc.arg(kind_matches)) match WHERE kind='activity' AND json_extract(activity,'$.family')=match.value) OR EXISTS(SELECT 1 FROM json_each(sqlc.arg(review_matches)) match WHERE json_extract(match.value,'$.kind')=display_review.kind AND (json_extract(match.value,'$.status')='' OR json_extract(match.value,'$.status')=display_review.status) AND (json_extract(match.value,'$.count_known')<>1 OR json_extract(match.value,'$.count')=claim_count)) ORDER BY kind,id LIMIT sqlc.arg(page_size) OFFSET sqlc.arg(page_offset);
-- name: AdminCandidate :one
SELECT artifact_id,authority,kind,scope,value,name,currency FROM eligible_candidates WHERE connection_id=? AND artifact_id=? AND authority=? AND kind=? AND scope=? AND value=? ORDER BY sequence DESC LIMIT 1;

-- name: AdminAccessSources :many
SELECT * FROM connections ORDER BY id;

-- name: AdminObservationCount :one
SELECT (SELECT count(*) FROM admin_observations o JOIN artifacts a ON a.id=o.artifact_id WHERE (o.subject_kind=sqlc.arg(subject_kind) AND o.subject_id=sqlc.arg(subject_id))) AS total,
count(*) AS matched FROM admin_observations o JOIN artifacts a ON a.id=o.artifact_id
WHERE (o.subject_kind=sqlc.arg(subject_kind) AND o.subject_id=sqlc.arg(subject_id)) AND (sqlc.arg(search)='' OR wake_contains(o.artifact_id || ' ' || coalesce(o.execution_id,'') || ' ' || o.location || ' ' || o.rule || ' ' || char(183) || ' ' || o.version || ' ' || a.retrieved,sqlc.arg(search))=1
 OR EXISTS(SELECT 1 FROM json_each(sqlc.arg(outcome_matches)) m WHERE m.value=o.outcome));
-- name: AdminObservationRows :many
WITH ordering AS (SELECT CAST(sqlc.arg(sort_field) AS TEXT) AS sort_field,CAST(sqlc.arg(direction) AS TEXT) AS direction,CAST(sqlc.arg(outcome_labels) AS TEXT) AS outcome_labels)
SELECT o.artifact_id,o.version,o.location,o.rule,o.outcome,o.execution_id,a.retrieved
FROM admin_observations o JOIN artifacts a ON a.id=o.artifact_id CROSS JOIN ordering
LEFT JOIN json_each(ordering.outcome_labels) labels ON labels.key=o.outcome
WHERE (o.subject_kind=sqlc.arg(subject_kind) AND o.subject_id=sqlc.arg(subject_id)) AND (sqlc.arg(search)='' OR wake_contains(o.artifact_id || ' ' || coalesce(o.execution_id,'') || ' ' || o.location || ' ' || o.rule || ' ' || char(183) || ' ' || o.version || ' ' || a.retrieved,sqlc.arg(search))=1
 OR EXISTS(SELECT 1 FROM json_each(sqlc.arg(outcome_matches)) m WHERE m.value=o.outcome))
ORDER BY CASE WHEN sort_field='report' AND direction='asc' THEN a.retrieved END COLLATE wake_instant asc,
CASE WHEN sort_field='report' AND direction='desc' THEN a.retrieved END COLLATE wake_instant desc,
CASE WHEN sort_field='outcome' AND direction='asc' THEN coalesce(labels.value,o.outcome) END COLLATE NOCASE asc,
CASE WHEN sort_field='outcome' AND direction='desc' THEN coalesce(labels.value,o.outcome) END COLLATE NOCASE desc,
CASE WHEN sort_field='activity' AND direction='asc' THEN o.execution_id END asc,
CASE WHEN sort_field='activity' AND direction='desc' THEN o.execution_id END desc,
CASE WHEN sort_field='location' AND direction='asc' THEN o.location END asc,
CASE WHEN sort_field='location' AND direction='desc' THEN o.location END desc,
CASE WHEN sort_field='rule' AND direction='asc' THEN o.rule || ' ' || char(183) || ' ' || o.version END asc,
CASE WHEN sort_field='rule' AND direction='desc' THEN o.rule || ' ' || char(183) || ' ' || o.version END desc,
o.artifact_id,o.version,o.location LIMIT sqlc.arg(page_size) OFFSET sqlc.arg(page_offset);
